"""Normal player input to inspect a real snowy village house after the level generates."""
def visit(aim, goto, shot, key, click, observe):
    # The snowy village is generated by Minecraft. Inside the house the eye can
    # see an open spruce doorway and its natural lanterns on either side.
    door=(-902,70,576)
    center=(-901.5,70.55,576.5)
    result={'village':shot('snowy-village',2)}
    goto((-899.5,69,574.5),'snowy-porch-east')
    goto((-901.5,68.9375,574.5),'snowy-doorstep')
    def target(label):
        o=aim(center,label,tries=5)
        return o
    o=target('closed-door')
    assert o['target'] in (door,(door[0],door[1]+1,door[2])),o
    result['closed']=shot('door-closed',2)
    key('1')
    click('3')
    open_obs=target('open-door')
    assert open_obs['target'] not in (door,(door[0],door[1]+1,door[2])),open_obs
    result['open']=shot('door-open',2)
    key('3')
    result['heldSoul']=shot('soul-at-door',2)
    key('1')
    goto((-901.5,70,577.5),'into-house',.35)
    inside=observe('inside-house',keep=True)
    assert int(inside['xyz'][1])==70
    result['inside']=shot('inside-house',2)
    result['doorClosedTarget']=o['target']
    result['doorOpenTarget']=open_obs['target']
    result['insidePosition']=inside['xyz']
    return result

def enter(aim, goto, shot, key, observe):
    # At the centre of the porch a low spruce crown intersects a player stepping
    # up from the path. Approach by the east stair so both feet and head clear it.
    # Keep space released: Minecraft steps smoothly up each half-stair.
    key("1")
    goto((-900.5,68.9,574.4),"outside-east",.2)
    goto((-900.5,68.9,575.45),"east-stair",.21)
    goto((-901.5,68.9,575.5),"onto-porch",.2)
    goto((-901.5,68.9,577.5),"enter-open-door",.23)
    inside=observe("inside-house",keep=True)
    assert -902<inside["xyz"][0]<-901 and 577<inside["xyz"][2]<578 and 69.99<=inside["xyz"][1]<=70.01
    aim((-901.5,71.5,579.5),"interior-window")
    bare=shot("naturally-lit-interior",2)
    key("3")
    held=shot("interior-soul-torch",2)
    key("1")
    return dict(insidePosition=inside["xyz"],inside=bare,heldSoul=held)

def to_plains(aim, goto, shot, key, click, observe):
    from pathlib import Path
    import json
    route=json.loads((Path(__file__).resolve().parent/'plains-route.json').read_text())
    key("1")
    door=(-902,70,576)
    test=aim((-901.5,70.55,576.5),'door-from-inside')
    if test['target'] in (door,(door[0],door[1]+1,door[2])):click("3")
    goto((-901.5,69,575.5),"out-onto-porch",.23)
    goto((-900.5,69,575.45),"out-east-stair",.23)
    goto(route['start'],"snowy-village-path",.23)
    result={"villageF3":observe("village-biome",keep=True)}
    leg=[]
    for i,waypoint in enumerate(route['waypoints'][1:],1):
        o=goto(waypoint,f"across-village-{i}",.31)
        leg.append(o['xyz'])
        if i in (len(route['waypoints'])//2,len(route['waypoints'])-1):
            x,y,z=o['xyz']
            aim((x-5,y+2.2,z+4),"weather-look")
            result["midway" if i<len(route['waypoints'])-1 else "plains"]=shot("weather-midway" if i<len(route['waypoints'])-1 else "weather-plains",2)
    result["plainsF3"]=observe("plains-biome",keep=True)
    result["waypointsReached"]=len(leg)
    result["end"]=leg[-1]
    return result
